#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

// Define a custom stack size, ensuring it's well above the minimum standard.
// PTHREAD_STACK_MIN is typically 16384 bytes, but may be undefined in some headers.
#ifndef PTHREAD_STACK_MIN
#define SAFE_STACK_MIN 16384
#else
#define SAFE_STACK_MIN PTHREAD_STACK_MIN
#endif

#define DESIRED_STACK_SIZE (SAFE_STACK_MIN * 4) // 64 KB

void* thread_routine(void* arg) {
    printf("\tNew thread started. (Argument check: %zu bytes)\n", *(size_t*)arg);
    return NULL;
}

int main() {
    pthread_attr_t attr;
    pthread_t thread_id;
    size_t verified_size = 0;
    int ret;

    // 1. Initialize attributes object
    ret = pthread_attr_init(&attr);
    if (ret != 0) {
        fprintf(stderr, "Error initializing attributes: %s\n", strerror(ret));
        return 1;
    }

    printf("Setting custom stack size to %zu bytes.\n", DESIRED_STACK_SIZE);

    // 2. Set the custom stack size attribute
    ret = pthread_attr_setstacksize(&attr, DESIRED_STACK_SIZE);
    if (ret != 0) {
        // EINVAL is the common error if size is too small or misaligned
        fprintf(stderr, "Error setting stack size: %s (Required size: >= %u)\n", 
                strerror(ret), SAFE_STACK_MIN);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 3. Verify the set size
    pthread_attr_getstacksize(&attr, &verified_size);
    printf("Verified stack size attribute: %zu bytes.\n", verified_size);

    // 4. Create the thread using the configured attributes
    ret = pthread_create(&thread_id, &attr, thread_routine, &verified_size);
    if (ret != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(ret));
    }

    // 5. Wait for the thread and clean up attributes
    pthread_join(thread_id, NULL);
    pthread_attr_destroy(&attr);

    return (ret == 0) ? 0 : 1;
}
